  reticle.position.set(o.x+d.x*t,o.y+d.y*t,o.z+d.z*t);reticle.rotation.set(s.p.pitch,-s.p.yaw,0,'YXZ');reticle.scale.setScalar(cameraWindow()?Math.max(.1,t*.012):1);reticle.visible=true;
 }
